Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -27,7 +27,91 @@
 <div class="mobile-controls" aria-label="Movement controls"><button data-dir="up" style="grid-column:2;grid-row:1">↑</button><button data-dir="left" style="grid-column:1;grid-row:2">←</button><button data-dir="down" style="grid-column:2;grid-row:2">↓</button><button data-dir="right" style="grid-column:3;grid-row:2">→</button></div>
 <div class="overlay" id="helpOverlay"><div class="modal"><h2>Find your wild</h2><p>Take a breath, choose a habitat, and see the world from another set of eyes. There’s no rush out here.</p><div class="guide-row"><strong>Move around</strong><span>W A S D or the on-screen arrows. Hold Shift to pick up the pace.</span></div><div class="guide-row"><strong>Explore</strong><span>Find five softly glowing field notes in each habitat to learn about the ecosystem.</span></div><div class="guide-row"><strong>Change view</strong><span>Choose terrestrial, aquatic, or flying at any time. Each animal has its own living world.</span></div><button class="close-btn" id="closeHelp">Back to the wild</button><div style="clear:both"></div></div></div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
+
+const canvas=document.querySelector('#world');
+const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
+renderer.setPixelRatio(Math.min(devicePixelRatio,2));
+renderer.setSize(innerWidth,innerHeight);
+renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
+renderer.outputColorSpace=THREE.SRGBColorSpace;
+renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;
+const scene=new THREE.Scene();scene.background=new THREE.Color('#dcefe4');
+const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,180);
+camera.position.set(0,4.2,8.5);
+const clock=new THREE.Clock();
+const hemi=new THREE.HemisphereLight(0xeaf5dd,0x687d53,2.1);scene.add(hemi);
+const sun=new THREE.DirectionalLight(0xfff1d0,3.2);sun.position.set(-7,12,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-18;sun.shadow.camera.right=18;sun.shadow.camera.top=18;sun.shadow.camera.bottom=-18;scene.add(sun);
+let worldGroup=new THREE.Group();scene.add(worldGroup);
+let actor=new THREE.Group();scene.add(actor);
+let mode='land',notes=[],collected=0,elapsed=0,toastTimer=0;
+const keys=new Set(),mobile=new Set();
+const state={x:0,y:0,z:0,vx:0,vy:0,vz:0,heading:0};
+const palettes={land:{bg:'#dcefe4',fog:'#dcefe4',region:'NORTHWOOD GROVE',title:'A world<br>to <em>wander.</em>',copy:'Follow the quiet paths. Every little discovery helps this wild place flourish.',animal:'Red fox',species:'Vulpes vulpes · terrestrial',emoji:'🦊',caption:'A protected place · Northwood reserve'},water:{bg:'#a6d9d8',fog:'#a6d9d8',region:'BLUEGLASS BAY',title:'Drift into<br>the <em>blue.</em>',copy:'Glide through the shallows. Small schools of life thrive beneath the surface.',animal:'Bottlenose dolphin',species:'Tursiops truncatus · aquatic',emoji:'🐬',caption:'A living reef · Blueglass marine reserve'},air:{bg:'#c4e3ec',fog:'#c4e3ec',region:'HIGHWIND CLIFFS',title:'Ride the<br><em>updraft.</em>',copy:'Catch the warm air above the cliffs. The whole valley opens up below.',animal:'Golden eagle',species:'Aquila chrysaetos · flying',emoji:'🦅',caption:'A migration route · Highwind sanctuary'}};
+const mat=(color,rough=.82,opts={})=>new THREE.MeshStandardMaterial({color,roughness:rough,...opts});
+const sphereGeo=new THREE.SphereGeometry(1,18,14);
+function blob(parent,color,pos,scale,opts={}){const m=new THREE.Mesh(sphereGeo,mat(color,.86,opts));m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
+function cylinder(parent,color,top,bottom,height,pos,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(top,bottom,height,segments),mat(color));m.position.set(...pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
+function group(parent,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
+function groundPlane(color,size=90,y=-.2){const m=new THREE.Mesh(new THREE.PlaneGeometry(size,size),mat(color));m.rotation.x=-Math.PI/2;m.position.y=y;m.receiveShadow=true;worldGroup.add(m);return m}
+function makeTree(x,z,scale=1,variant=0){const g=group(worldGroup,x,0,z);let trunk=cylinder(g,variant?'#896546':'#7b6648',.22,.34,2.1,[0,1.05,0],7);trunk.scale.setScalar(scale);const colors=['#54875d','#689660','#7a9c5e','#497b59'];for(let i=0;i<3;i++){let c=blob(g,colors[(variant+i)%colors.length],[0,2.15+i*.48,0],[.9-i*.08,.92-i*.04,.86-i*.06]);c.scale.multiplyScalar(scale);c.position.y*=scale;c.position.x*=scale;c.position.z*=scale;}g.scale.setScalar(scale);return g}
+function makeRock(x,y,z,s=1,color='#9da991'){let r=blob(worldGroup,color,[x,y,z],[s*1.1,s*.6,s*.8]);r.rotation.y=Math.random()*2;return r}
+function makeFlower(x,z,color){const g=group(worldGroup,x,0,z);cylinder(g,'#779b55',.035,.035,.28,[0,.14,0],5);blob(g,color,[0,.31,0],[.12,.1,.12]);for(let i=0;i<4;i++){const a=i*Math.PI/2;blob(g,color,[Math.cos(a)*.12,.3,Math.sin(a)*.12],[.075,.07,.07]);}return g}
+function makeCloud(x,y,z,s=1){const g=group(worldGroup,x,y,z);[[0,0,0],[.7,.1,0],[-.65,.05,.1],[.12,.3,0]].forEach(([a,b,c],i)=>blob(g,'#f1f8f2',[a,b,c],[.8-i*.05,.43+i*.03,.5]));g.scale.setScalar(s);return g}
+function makeAnimal(kind){actor.clear();actor.position.set(state.x,state.y,state.z);let g=group(actor);if(kind==='land'){
+  blob(g,'#b96938',[0,.68,0],[.53,.61,.92]);blob(g,'#d58b54',[0,.66,-.48],[.46,.48,.54]);blob(g,'#e5bd87',[0,.48,-.9],[.32,.24,.31]);blob(g,'#b96938',[0,.79,-.98],[.34,.31,.34]);blob(g,'#dfa05e',[0,.63,-1.22],[.2,.15,.22]);blob(g,'#362f29',[0,.68,-1.4],[.095,.075,.1]);
+  for(const s of [-1,1]){const ear=blob(g,'#b96938',[s*.23,1.12,-.91],[.15,.33,.13]);ear.rotation.z=-s*.18;blob(g,'#f2c38b',[s*.23,1.13,-.995],[.078,.21,.045]);blob(g,'#262d28',[s*.29,.83,-1.07],[.045,.055,.04]);blob(g,'#f5e8ce',[s*.3,.85,-1.105],[.013,.014,.012]);}
+  const tail=blob(g,'#bb6939',[0,.77,.82],[.28,.32,.72]);tail.rotation.x=-.48;blob(g,'#f2e6d0',[0,.56,1.39],[.23,.2,.24]);
+  const legs=[];for(const x of [-.32,.32])for(const z of [-.49,.53]){const leg=blob(g,'#9b502f',[x,.32,z],[.14,.42,.16]);legs.push(leg);blob(g,'#4e4337',[x,.08,z-.025],[.15,.1,.19]);}g.userData.legs=legs;g.userData.tail=tail;
+ }else if(kind==='water'){
+  const body=blob(g,'#6eb8b7',[0,0,0],[.47,.5,1.34]);body.rotation.x=.04;blob(g,'#a9d8cd',[0,-.27,-.13],[.38,.2,1.02]);blob(g,'#5da8a9',[0,.02,-1.13],[.34,.32,.42]);blob(g,'#62aeb0',[0,-.02,-1.42],[.25,.18,.27]);blob(g,'#244950',[0,-.08,-1.62],[.09,.055,.11]);for(const s of [-1,1]){blob(g,'#253f42',[s*.26,.14,-1.21],[.045,.045,.045]);const fin=blob(g,'#459697',[s*.43,-.23,-.15],[.19,.08,.42]);fin.rotation.z=s*.3;}const dorsal=blob(g,'#509a9c',[0,.49,.05],[.16,.33,.28]);dorsal.rotation.z=.25;const tail=group(g,0,0,1.22);blob(tail,'#4a9699',[.25,0,.12],[.32,.09,.38]).rotation.y=.38;blob(tail,'#4a9699',[-.25,0,.12],[.32,.09,.38]).rotation.y=-.38;g.userData.tail=tail;
+ }else{
+  blob(g,'#8a7455',[0,.15,0],[.48,.57,.72]);blob(g,'#b9a17a',[0,.02,-.48],[.32,.38,.35]);blob(g,'#d4ba71',[0,-.02,-.76],[.23,.19,.3]);blob(g,'#d29d3e',[0,-.06,-.99],[.07,.08,.2]);for(const s of [-1,1]){blob(g,'#242b27',[s*.15,.12,-.65],[.055,.06,.04]);blob(g,'#f4e3b9',[s*.166,.14,-.69],[.016,.018,.012]);cylinder(g,'#ca9b43',.035,.035,.34,[s*.22,-.42,.05],6);}
+  const wings=[];for(const s of [-1,1]){const w=group(g,s*.27,.33,0);const wing=blob(w,'#907d60',[s*.65,0,.07],[.85,.13,.32]);wing.rotation.y=s*.08;for(let i=0;i<4;i++){const f=blob(w,i%2?'#7b6e59':'#a18c67',[s*(.65+i*.15),-.03,.27+i*.085],[.35,.08,.12]);f.rotation.y=s*.13;}wings.push(w);}g.userData.wings=wings;
+ }
+ actor.userData.body=g;return g;}
+function addReeds(x,z){const g=group(worldGroup,x,0,z);for(let i=0;i<4;i++){let h=.5+Math.random()*.7;let r=cylinder(g,i%2?'#529b8b':'#6da68b',.025,.045,h,[Math.sin(i*2)*.2,h/2,Math.cos(i*2)*.2],5);r.rotation.z=(Math.random()-.5)*.24;}}
+function buildLand(){scene.background=new THREE.Color('#dcefe4');scene.fog=new THREE.Fog('#dcefe4',22,62);groundPlane('#91ad72',100,-.16);const island=blob(worldGroup,'#a7bd7b',[0,-.56,0],[21,.6,21]);island.receiveShadow=true;
+ // A softly rolling clearing at the center, framed by woodland.
+ [[-10,-9,4.5],[-13,3,5],[11,-12,4],[14,2,5],[8,12,5],[-10,13,4.5]].forEach(([x,z,s],i)=>{const h=blob(worldGroup,i%2?'#88a86b':'#94ad70',[x,-.15,z],[s,.9,s*.82]);h.position.y=-.22;});
+ for(let i=0;i<54;i++){const a=Math.random()*Math.PI*2,r=14+Math.random()*9,x=Math.cos(a)*r,z=Math.sin(a)*r;makeTree(x,z,.65+Math.random()*.7,i%3);}for(let i=0;i<18;i++){let x=(Math.random()-.5)*27,z=(Math.random()-.5)*27;if(Math.abs(x)>7||Math.abs(z)>7)makeRock(x,0,z,.3+Math.random()*.65,i%2?'#aab492':'#929e7e');}
+ for(let i=0;i<26;i++){let x=(Math.random()-.5)*13,z=(Math.random()-.5)*13;if(Math.hypot(x,z)>2)makeFlower(x,z,['#f2dd9b','#e6b9a8','#d3de9b'][i%3]);}
+ // sunlit woodland arch and winding path stones
+ for(let i=0;i<13;i++){let z=-9+i*1.45;makeRock(Math.sin(i*.48)*1.1,0,z,.35,'#c6bd91');}
+}
+function buildWater(){scene.background=new THREE.Color('#a6d9d8');scene.fog=new THREE.Fog('#a6d9d8',15,55);groundPlane('#286d70',85,-5.7);const water=new THREE.Mesh(new THREE.PlaneGeometry(90,90),new THREE.MeshStandardMaterial({color:'#53aaa9',roughness:.27,metalness:.08,transparent:true,opacity:.66}));water.rotation.x=-Math.PI/2;water.position.y=.9;worldGroup.add(water);const sand=blob(worldGroup,'#b5bd91',[0,-5.3,0],[24,.45,24]);sand.receiveShadow=true;
+ for(let i=0;i<27;i++){let a=Math.random()*6.28,r=7+Math.random()*15,x=Math.cos(a)*r,z=Math.sin(a)*r;let b=blob(worldGroup,['#398b8a','#4d9690','#5b9e8d'][i%3],[x,-4.8,z],[.6+Math.random(),.3,.5+Math.random()]);b.rotation.y=Math.random()*3;}
+ for(let i=0;i<32;i++){let x=(Math.random()-.5)*34,z=(Math.random()-.5)*34;addReeds(x,z);}
+ for(let i=0;i<13;i++){let x=(Math.random()-.5)*28,z=-10+Math.random()*20;let c=blob(worldGroup,i%2?'#f18e78':'#e9ad83',[x,-3.9,z],[.35,.65,.32]);for(let k=0;k<4;k++)blob(worldGroup,'#f6c68c',[x+(Math.random()-.5)*.4,-3.25+Math.random()*.45,z+(Math.random()-.5)*.4],[.12,.14,.12]);}
+ // Fish families make the water feel inhabited.
+ for(let i=0;i<14;i++){const f=group(worldGroup,(Math.random()-.5)*18,-2.2+Math.random()*1.8,-7+Math.random()*16);blob(f,i%2?'#f4d18c':'#d6ecba',[0,0,0],[.13,.09,.24]);const tail=blob(f,'#f3bc75',[0,0,.25],[.1,.07,.12]);tail.rotation.y=.4;f.userData.phase=Math.random()*6;f.userData.home=f.position.clone();f.userData.fish=true;}
+ for(let i=0;i<14;i++){let x=(Math.random()-.5)*28,z=(Math.random()-.5)*30;let b=blob(worldGroup,'#d9f4d7',[x,-.5-Math.random()*3,z],[.035,.035,.035],{emissive:'#8de6da',emissiveIntensity:1});b.userData.bubble=true;b.userData.speed=.3+Math.random()*.6;b.userData.baseY=b.position.y;}
+}
+function buildAir(){scene.background=new THREE.Color('#c4e3ec');scene.fog=new THREE.Fog('#c4e3ec',27,90);groundPlane('#acc786',100,-.2);const island=blob(worldGroup,'#85a66c',[0,-.7,0],[19,.8,17]);island.receiveShadow=true;const turf=blob(worldGroup,'#9fba77',[0,-.25,0],[17,.65,15]);
+ for(let i=0;i<28;i++){let a=Math.random()*6.28,r=11+Math.random()*9;makeTree(Math.cos(a)*r,Math.sin(a)*r,.48+Math.random()*.55,i%4);}for(let i=0;i<20;i++){let x=(Math.random()-.5)*25,z=(Math.random()-.5)*24;makeRock(x,0,z,.35+Math.random()*.55,'#99a880');}
+ for(let i=0;i<9;i++){let x=(Math.random()-.5)*52,z=-28+Math.random()*55;makeCloud(x,4+Math.random()*11,z,.7+Math.random()*1.4);}
+ // Distant suspended cloud-islands add scale and a homeward horizon.
+ for(let i=0;i<7;i++){let x=(Math.random()-.5)*44,z=-23+Math.random()*50;const isl=blob(worldGroup,'#9ab59a',[x,-1.8,z],[2+Math.random()*3,.45,2+Math.random()*3]);blob(worldGroup,'#d2dfc4',[x,-1.42,z],[1.8,.22,1.8]);}
+}
+function spawnNotes(){for(const n of notes)worldGroup.remove(n);notes=[];const glow=mode==='water'?'#9cf4df':mode==='air'?'#ecf6bd':'#e9eda0';for(let i=0;i<7;i++){let a=(i/7)*Math.PI*2+.38,r=4.5+(i%3)*2.1;let y=mode==='water'?-1.35+(i%2)*.65:mode==='air'?.8+(i%3)*.65:.15;let g=group(worldGroup,Math.cos(a)*r,y,Math.sin(a)*r-2);const core=blob(g,glow,[0,0,0],[.17,.17,.17],{emissive:glow,emissiveIntensity:1.2});const halo=new THREE.Mesh(new THREE.TorusGeometry(.3,.018,8,24),new THREE.MeshBasicMaterial({color:glow,transparent:true,opacity:.78}));halo.rotation.x=Math.PI/2;g.add(halo);g.userData.phase=i;g.userData.core=core;notes.push(g);}}
+function resetState(){state.x=0;state.z=0;state.y=mode==='water'?-1.25:0;state.heading=0;state.vx=state.vy=state.vz=0;actor.position.set(0,state.y,0);}
+function enterMode(next){mode=next;worldGroup.clear();if(next==='land')buildLand();if(next==='water')buildWater();if(next==='air')buildAir();resetState();makeAnimal(next);collected=0;spawnNotes();updateUI();document.querySelectorAll('.mode-button').forEach(b=>b.classList.toggle('active',b.dataset.mode===next));}
+function updateUI(){const p=palettes[mode];document.querySelector('#regionLabel').textContent=p.region+' · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});document.querySelector('#heroTitle').innerHTML=p.title;document.querySelector('#heroCopy').textContent=p.copy;document.querySelector('#animalName').textContent=p.animal;document.querySelector('#animalSpecies').textContent=p.species;document.querySelector('#animalEmoji').textContent=p.emoji;document.querySelector('#worldCaption').textContent=p.caption;document.querySelector('#climateLabel').textContent=mode==='water'?'Water clarity':mode==='air'?'Wind conditions':'Air quality';document.querySelector('#airValue').textContent=mode==='water'?'Very clear':mode==='air'?'Gentle':'Clear';document.querySelector('#missionDesc').textContent=mode==='water'?'Collect five drifting reef-glimmers hidden in the shallows.':mode==='air'?'Find five sunlit pollen motes above the highland canopy.':'Find the glowing wildflower seeds scattered around your habitat.';document.querySelector('#missionBadge').textContent=mode==='water'?'Observe':mode==='air'?'Soar':'Explore';document.querySelector('#habitatStatus').textContent=mode==='water'?'REEF PROTECTED':mode==='air'?'SANCTUARY OPEN':'HABITAT THRIVING';document.querySelector('#progressCount').textContent=collected+' / 5';document.querySelector('#progressFill').style.width=Math.min(collected/5*100,100)+'%';document.querySelector('#signalTotal').textContent=Number(localStorage.getItem('wildboundNotes')||0);document.querySelector('#bioValue').textContent=collected>=5?'92%':'86%';document.querySelector('#bioMeter').style.width=collected>=5?'92%':'86%';document.querySelector('#healthWord').textContent=collected>=5?'FLOURISHING':'BALANCED';}
+function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');toastTimer=2.3;}
+function getAxis(){let x=0,z=0,y=0;if(keys.has('KeyA')||keys.has('ArrowLeft')||mobile.has('left'))x--;if(keys.has('KeyD')||keys.has('ArrowRight')||mobile.has('right'))x++;if(keys.has('KeyW')||keys.has('ArrowUp')||mobile.has('up'))z--;if(keys.has('KeyS')||keys.has('ArrowDown')||mobile.has('down'))z++;if(mode==='air'){if(keys.has('Space')||keys.has('KeyE'))y++;if(keys.has('KeyC')||keys.has('ControlLeft'))y--;}return {x,z,y};}
+function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));}
+window.addEventListener('resize',resize);
+window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Escape')document.querySelector('#helpOverlay').classList.toggle('open');});window.addEventListener('keyup',e=>keys.delete(e.code));
+document.querySelectorAll('.mode-button').forEach(b=>b.addEventListener('click',()=>enterMode(b.dataset.mode)));
+document.querySelector('#helpBtn').addEventListener('click',()=>document.querySelector('#helpOverlay').classList.add('open'));document.querySelector('#closeHelp').addEventListener('click',()=>document.querySelector('#helpOverlay').classList.remove('open'));document.querySelector('#helpOverlay').addEventListener('click',e=>{if(e.target.id==='helpOverlay')e.currentTarget.classList.remove('open')});
+document.querySelectorAll('.mobile-controls button').forEach(b=>{const d=b.dataset.dir;for(const ev of ['pointerdown','pointerenter'])b.addEventListener(ev,e=>{if(e.buttons||ev==='pointerdown'){mobile.add(d);b.setPointerCapture?.(e.pointerId)}});for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>mobile.delete(d));});
+function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;const ax=getAxis(),moving=Math.hypot(ax.x,ax.z)>0;const norm=Math.hypot(ax.x,ax.z)||1,sprint=keys.has('ShiftLeft')||keys.has('ShiftRight');const speed=(mode==='water'?3.5:mode==='air'?4.7:3.25)*(sprint?1.7:1);state.vx+=(ax.x/norm*speed-state.vx)*Math.min(1,dt*5);state.vz+=(ax.z/norm*speed-state.vz)*Math.min(1,dt*5);state.x+=state.vx*dt;state.z+=state.vz*dt;state.x=THREE.MathUtils.clamp(state.x,-24,24);state.z=THREE.MathUtils.clamp(state.z,-25,25);if(mode==='air'){state.vy+=(ax.y*2.7-state.vy)*Math.min(1,dt*3);state.y=THREE.MathUtils.clamp(state.y+state.vy*dt,-.1,7.5);}else if(mode==='water'){state.y=-1.25+Math.sin(elapsed*1.1)*.12;}else state.y=0;
+ actor.position.set(state.x,state.y+(moving?(mode==='air'?Math.sin(elapsed*7)*.07:mode==='water'?Math.sin(elapsed*5)*.045:Math.abs(Math.sin(elapsed*11))*.06):0),state.z);if(moving){state.heading=Math.atan2(-ax.x,-ax.z);actor.rotation.y=THREE.MathUtils.lerp(actor.rotation.y,state.heading,dt*5);}const body=actor.userData.body;if(body?.userData.legs)body.userData.legs.forEach((l,i)=>{l.position.y=.32+(moving?Math.sin(elapsed*12+i*Math.PI)*.1:0)});if(body?.userData.tail){if(mode==='land')body.userData.tail.rotation.z=Math.sin(elapsed*3)*.12;if(mode==='water')body.userData.tail.rotation.x=Math.sin(elapsed*7)*.28;}if(body?.userData.wings)body.userData.wings.forEach((w,i)=>{w.rotation.z=(i===0?1:-1)*Math.sin(elapsed*(moving?8:2.5))*(moving?.42:.12)});
+ const follow=mode==='air'?5.4:mode==='water'?4.1:4.7;const target=new THREE.Vector3(state.x*.76,state.y+(mode==='air'?2.1:mode==='water'?1.7:1.9),state.z+follow);camera.position.lerp(target,1-Math.pow(.002,dt));camera.lookAt(state.x,state.y+(mode==='water'?-.15:.55),state.z-1.6);
+ worldGroup.children.forEach(o=>{if(o.userData.phase!==undefined){o.position.y+=(Math.sin(elapsed*2+o.userData.phase)*.18+0)*dt;o.rotation.y+=dt*.32;}if(o.userData.fish){o.position.x=o.userData.home.x+Math.sin(elapsed*.65+o.userData.phase)*.7;o.position.z=o.userData.home.z+Math.cos(elapsed*.5+o.userData.phase)*.7;}if(o.userData.bubble){o.position.y+=dt*o.userData.speed;if(o.position.y>.8)o.position.y=-4.5;}});
+ for(let i=notes.length-1;i>=0;i--){const n=notes[i];n.rotation.y+=dt*.7;n.position.y+=Math.sin(elapsed*2+n.userData.phase)*dt*.12;const d=Math.hypot(state.x-n.position.x,state.z-n.position.z, (state.y-n.position.y)*.65);if(d<1.35){worldGroup.remove(n);notes.splice(i,1);collected++;const total=Number(localStorage.getItem('wildboundNotes')||0)+1;localStorage.setItem('wildboundNotes',total);updateUI();showToast(collected>=5?'Habitat flourishing · field notes complete!':'Field note found · the habitat thanks you');}}
+ if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show');}renderer.render(scene,camera);}
